-- rails: route and lay train rails (straight, diagonal, curves) with the geometry learned from the game.
-- scripts/rail_table.lua says which piece connects to which end of which piece (generated by
-- tools/calibrate_rails.py from the real game, so there is no hand-written geometry here).
-- Search: A* over rail ends. Placement: piece by piece, then the connection is verified with the
-- game's own rail API; on any failure everything placed is picked up again.
local C = require("scripts.common")
local T = require("scripts.rail_table")
local M = {}

local fail, done = C.fail, C.done
local surf, agent, bag = C.surf, C.agent, C.bag

local PIECES = T.pieces
local RAIL_TYPES = { "straight-rail", "half-diagonal-rail", "curved-rail-a", "curved-rail-b" }
local ITEM_COUNT = { ["straight-rail"] = 1, ["half-diagonal-rail"] = 2, ["curved-rail-a"] = 3, ["curved-rail-b"] = 3 }
local NODE_LIMIT = 40000
local HEURISTIC_WEIGHT = 1.25 -- slightly greedy: much faster on long lines, the route stays near the shortest
local MARGIN = 30
local CURVE_PENALTY = 1.5
local REUSE_COST = 0.3
local OBSTACLE_COST = 1.0 -- per tree or rock that has to be removed

local DIRS16 = { north = 0, northnortheast = 1, northeast = 2, eastnortheast = 3, east = 4, eastsoutheast = 5, southeast = 6,
  southsoutheast = 7, south = 8, southsouthwest = 9, southwest = 10, westsouthwest = 11, west = 12, westnorthwest = 13,
  northwest = 14, northnorthwest = 15 }

local function key(name, dir) return name .. "|" .. dir end

-- every transition learns which end of the next piece is the open one (the end we leave through)
local LENGTH = {}
for k, p in pairs(PIECES) do
  local f, b = p.front.end_rel, p.back.end_rel
  LENGTH[k] = math.sqrt((f[1] - b[1]) ^ 2 + (f[2] - b[2]) ^ 2)
  for _, endname in ipairs { "front", "back" } do
    for _, n in ipairs(p[endname].next) do
      local np = PIECES[key(n[2], n[3])]
      n.exit = nil
      if np then
        for _, en in ipairs { "front", "back" } do
          local e = np[en]
          if e.end_dir == n[6] and e.end_rel[1] + n[4] == n[7] and e.end_rel[2] + n[5] == n[8] then n.exit = en end
        end
      end
    end
  end
end

M.PIECES = PIECES

----------------------------------------------------------------------------- binary heap
local function heap_push(h, item)
  h[#h + 1] = item
  local i = #h
  while i > 1 do
    local p = math.floor(i / 2)
    if h[p].f <= h[i].f then break end
    h[p], h[i] = h[i], h[p]
    i = p
  end
end

local function heap_pop(h)
  local top = h[1]
  local last = h[#h]
  h[#h] = nil
  local n = #h
  if n > 0 then
    h[1] = last
    local i = 1
    while true do
      local l, r, m = i * 2, i * 2 + 1, i
      if l <= n and h[l].f < h[m].f then m = l end
      if r <= n and h[r].f < h[m].f then m = r end
      if m == i then break end
      h[m], h[i] = h[i], h[m]
      i = m
    end
  end
  return top
end

----------------------------------------------------------------------------- search (pure, no game access)

local function exit_of(node)
  local e = PIECES[key(node.name, node.dir)][node.exit]
  return node.x + e.end_rel[1], node.y + e.end_rel[2], e.end_dir
end

-- o.starts   list of { name, dir, x, y, exit, existing }  (existing = already built, not part of the result)
-- o.goal     { x, y, dir? }, o.tolerance (tiles, default 1.0)
-- o.can_place(name, dir, x, y) -> ok, obstacles  (obstacles = number of trees/rocks that must be removed first)
-- o.reuse(name, dir, x, y) -> bool (same rail already there)
-- returns a list of { name, dir, x, y, exit, reused } or nil, reason
function M.search(o)
  local goal, tol = o.goal, o.tolerance or 1.0
  local limit = o.limit or NODE_LIMIT
  local b = o.bounds
  local open, best = {}, {}
  local expanded = 0

  local function heuristic(x, y)
    local d = math.sqrt((x - goal.x) ^ 2 + (y - goal.y) ^ 2) - tol
    return d > 0 and d or 0
  end

  local function push(node)
    local k = key(node.name, node.dir) .. "|" .. node.x .. "|" .. node.y .. "|" .. node.exit
    if best[k] and best[k] <= node.g then return end
    best[k] = node.g
    local ex, ey = exit_of(node)
    node.f = node.g + HEURISTIC_WEIGHT * heuristic(ex, ey)
    heap_push(open, node)
  end

  for _, s in ipairs(o.starts) do
    local node = { name = s.name, dir = s.dir, x = s.x, y = s.y, exit = s.exit, g = 0, existing = s.existing }
    if s.existing then
      push(node)
    else
      local ok, obstacles = o.can_place(s.name, s.dir, s.x, s.y)
      if ok then
        node.obstacles = obstacles or 0
        node.g = LENGTH[key(s.name, s.dir)] + node.obstacles * OBSTACLE_COST
        push(node)
      end
    end
  end
  if #open == 0 then return nil, "no_start" end

  while #open > 0 do
    local cur = heap_pop(open)
    local ex, ey, edir = exit_of(cur)
    local dist = math.sqrt((ex - goal.x) ^ 2 + (ey - goal.y) ^ 2)
    if dist <= tol and (goal.dir == nil or goal.dir == edir) then
      local path = {}
      local n = cur
      while n do
        if not n.existing then table.insert(path, 1, n) end
        n = n.parent
      end
      return path
    end
    expanded = expanded + 1
    if expanded > limit then return nil, "limit" end
    for _, n in ipairs(PIECES[key(cur.name, cur.dir)][cur.exit].next) do
      if n.exit then
        local nx, ny = cur.x + n[4], cur.y + n[5]
        if not b or (nx >= b.minx and nx <= b.maxx and ny >= b.miny and ny <= b.maxy) then
          local reused = o.reuse and o.reuse(n[2], n[3], nx, ny)
          local ok, obstacles = false, 0
          if not reused then ok, obstacles = o.can_place(n[2], n[3], nx, ny) end
          if reused or ok then
            obstacles = obstacles or 0
            local cost = reused and REUSE_COST or (LENGTH[key(n[2], n[3])] + obstacles * OBSTACLE_COST)
            if n[1] ~= "straight" then cost = cost + CURVE_PENALTY end
            push { name = n[2], dir = n[3], x = nx, y = ny, exit = n.exit, g = cur.g + cost, parent = cur, reused = reused, obstacles = obstacles }
          end
        end
      end
    end
  end
  return nil, "no_path"
end

----------------------------------------------------------------------------- game access

local function rail_direction(exit)
  return exit == "front" and defines.rail_direction.front or defines.rail_direction.back
end

local function connected(from_entity, exit, to_entity)
  for _, cd in ipairs { defines.rail_connection_direction.left, defines.rail_connection_direction.straight, defines.rail_connection_direction.right } do
    local e = from_entity.get_rail_end(rail_direction(exit))
    if e.move_forward(cd) and e.rail and e.rail.valid and e.rail.unit_number == to_entity.unit_number then return true end
  end
  return false
end

-- open ends of rails near (x, y): { name, dir, x, y, exit, end_x, end_y, end_dir }
local function open_ends(x, y, radius)
  local result = {}
  local s, a = surf(), agent()
  local area = { { x - radius, y - radius }, { x + radius, y + radius } }
  for _, ent in ipairs(s.find_entities_filtered { area = area, type = RAIL_TYPES, force = a.force }) do
    if ent.valid and PIECES[key(ent.name, ent.direction)] then
      for _, exit in ipairs { "front", "back" } do
        local e = ent.get_rail_end(rail_direction(exit))
        local is_open = true
        for _, cd in ipairs { defines.rail_connection_direction.left, defines.rail_connection_direction.straight, defines.rail_connection_direction.right } do
          if e.make_copy().move_forward(cd) then is_open = false; break end
        end
        if is_open then
          local loc = e.location
          result[#result + 1] = {
            name = ent.name, dir = ent.direction, x = math.floor(ent.position.x + 0.5), y = math.floor(ent.position.y + 0.5), exit = exit,
            end_x = loc.position.x, end_y = loc.position.y, end_dir = loc.direction,
            dist = math.sqrt((loc.position.x - x) ^ 2 + (loc.position.y - y) ^ 2),
          }
        end
      end
    end
  end
  table.sort(result, function(p, q) return p.dist < q.dist end)
  return result
end

function M.rail_end(x, y, radius)
  local list = open_ends(x, y, math.min(radius or 6, 20))
  local out = {}
  for i, e in ipairs(list) do
    if i > 12 then break end
    out[#out + 1] = { piece = e.name, x = e.x, y = e.y, end_x = e.end_x, end_y = e.end_y, end_direction = e.end_dir }
  end
  return done { ends = out, count = #list }
end

-- bounding box around a piece (both ends and the centre, a little extra room)
local function piece_box(name, dir, x, y)
  local p = PIECES[key(name, dir)]
  local xs = { x, x + p.front.end_rel[1], x + p.back.end_rel[1] }
  local ys = { y, y + p.front.end_rel[2], y + p.back.end_rel[2] }
  return { { math.min(xs[1], xs[2], xs[3]) - 1.2, math.min(ys[1], ys[2], ys[3]) - 1.2 },
           { math.max(xs[1], xs[2], xs[3]) + 1.2, math.max(ys[1], ys[2], ys[3]) + 1.2 } }
end

local REMOVABLE = { "tree", "simple-entity" } -- rocks are simple entities
local NOT_BLOCKING = { resource = true, character = true, corpse = true, ["item-entity"] = true, ["entity-ghost"] = true, ["tile-ghost"] = true }

-- trees and rocks inside the box; second result: true when something else (building, cliff, water) is in the way
local function scan_box(box)
  local s = surf()
  local removable, other = {}, false
  for _, e in ipairs(s.find_entities_filtered { area = box }) do
    if e.valid then
      if e.type == "tree" or e.type == "simple-entity" then
        removable[#removable + 1] = e
      elseif not NOT_BLOCKING[e.type] then
        other = true
      end
    end
  end
  if not other then
    for _, t in ipairs(s.find_tiles_filtered { area = box, collision_mask = "water_tile" }) do
      other = true
      break
    end
  end
  return removable, other
end

local function lattice(v) return math.floor(v / 2) * 2 + 1 end

local function rollback(placed)
  for _, e in ipairs(placed) do
    if e.valid then e.destroy() end
  end
end

-- end_direction: nil, a direction name or 0..15 (direction of the last rail end, pointing away from the line)
function M.connect(x1, y1, x2, y2, end_direction, dry_run, keep_trees)
  local s, a = surf(), agent()
  local goal = { x = x2, y = y2 }
  if end_direction ~= nil and end_direction ~= "" then
    local d = tonumber(end_direction) or DIRS16[end_direction]
    if d == nil then return fail("bad_direction", "end_direction must be north, east, south, west, a 16-way name or 0..15", { direction = end_direction }) end
    goal.dir = d % 16
  end

  local place_cache, reuse_cache = {}, {}
  local function can_place(name, dir, x, y)
    local k = key(name, dir) .. "|" .. x .. "|" .. y
    local v = place_cache[k]
    if v == nil then
      if s.can_place_entity { name = name, position = { x, y }, direction = dir, force = a.force } then
        v = { true, 0 }
      elseif keep_trees then
        v = { false, 0 }
      else
        local removable, other = scan_box(piece_box(name, dir, x, y))
        v = (not other and #removable > 0) and { true, #removable } or { false, 0 }
      end
      place_cache[k] = v
    end
    return v[1], v[2]
  end
  local function reuse(name, dir, x, y)
    local k = key(name, dir) .. "|" .. x .. "|" .. y
    local v = reuse_cache[k]
    if v == nil then
      local ent = s.find_entity(name, { x, y })
      v = ent ~= nil and ent.valid and ent.direction == dir and ent.force == a.force
      reuse_cache[k] = v
    end
    return v
  end

  -- start: continue an open rail end within 3 tiles, otherwise start a new line at (x1, y1)
  local starts, start_entity, start_exit = {}, nil, nil
  local ends = open_ends(x1, y1, 3)
  if #ends > 0 and ends[1].dist <= 3 then
    local e = ends[1]
    starts[1] = { name = e.name, dir = e.dir, x = e.x, y = e.y, exit = e.exit, existing = true }
    start_entity = s.find_entity(e.name, { e.x, e.y })
    start_exit = e.exit
  else
    local lx, ly = lattice(x1), lattice(y1)
    for _, dir in ipairs { 0, 2, 4, 6 } do
      for _, exit in ipairs { "front", "back" } do
        starts[#starts + 1] = { name = "straight-rail", dir = dir, x = lx, y = ly, exit = exit }
      end
    end
  end

  local bounds = {
    minx = math.min(x1, x2) - MARGIN, maxx = math.max(x1, x2) + MARGIN,
    miny = math.min(y1, y2) - MARGIN, maxy = math.max(y1, y2) + MARGIN,
  }
  local path, why = M.search { starts = starts, goal = goal, can_place = can_place, reuse = reuse, bounds = bounds }
  if not path then
    local msg = why == "no_start" and "cannot start a rail at " .. x1 .. "," .. y1 .. " (blocked, or no space for a straight piece)"
      or why == "limit" and "search limit reached; try a shorter distance or a waypoint in between"
      or "no rail route from " .. x1 .. "," .. y1 .. " to " .. x2 .. "," .. y2 .. " (blocked by water, cliffs, buildings or trees)"
    return fail("no_path", msg, { reason = why })
  end

  local needed, counts, obstacles = 0, {}, 0
  for _, n in ipairs(path) do
    obstacles = obstacles + (n.obstacles or 0)
    if not n.reused then
      needed = needed + ITEM_COUNT[n.name]
      counts[n.name] = (counts[n.name] or 0) + 1
    end
  end
  local inventory = bag()
  local have = inventory.get_item_count("rail")
  local last = path[#path]
  local lx, ly, ldir
  if last then lx, ly, ldir = (function() local e = PIECES[key(last.name, last.dir)][last.exit]; return last.x + e.end_rel[1], last.y + e.end_rel[2], e.end_dir end)() end
  if dry_run then
    return done { item = "rail", needed = needed, have = have, enough = have >= needed, pieces = #path, by_type = counts,
                  continues_existing = start_entity ~= nil, trees_to_clear = obstacles > 0 and obstacles or nil, to = lx and { x = lx, y = ly, direction = ldir } or nil }
  end
  if have < needed then
    return fail("missing", "missing " .. (needed - have) .. " rail", { item = "rail", count = needed - have, needed = needed, have = have })
  end

  C.stand_off({ x = x1, y = y1 })
  if needed > 0 and inventory.remove { name = "rail", count = needed } ~= needed then
    return fail("missing", "could not take " .. needed .. " rail from the inventory", { item = "rail", needed = needed })
  end
  local entities, placed, cleared = {}, {}, 0
  local function create(n)
    return s.create_entity { name = n.name, position = { n.x, n.y }, direction = n.dir, force = a.force, raise_built = true }
  end
  for i, n in ipairs(path) do
    local ent
    if n.reused then
      ent = s.find_entity(n.name, { n.x, n.y })
    else
      ent = s.can_place_entity { name = n.name, position = { n.x, n.y }, direction = n.dir, force = a.force } and create(n) or nil
      if not ent and not keep_trees and (n.obstacles or 0) > 0 then
        -- cut the trees and rocks in the way one by one (nearest first) until the piece fits
        for _ = 1, 25 do
          local removable, other = scan_box(piece_box(n.name, n.dir, n.x, n.y))
          if other or #removable == 0 then break end
          table.sort(removable, function(p, q)
            return (p.position.x - n.x) ^ 2 + (p.position.y - n.y) ^ 2 < (q.position.x - n.x) ^ 2 + (q.position.y - n.y) ^ 2
          end)
          local victim = removable[1]
          local mined = false
          pcall(function() mined = victim.mine { inventory = inventory } end)
          if not mined and victim.valid then victim.destroy() end
          cleared = cleared + 1
          if s.can_place_entity { name = n.name, position = { n.x, n.y }, direction = n.dir, force = a.force } then
            ent = create(n)
            break
          end
        end
      end
      if ent then placed[#placed + 1] = ent end
    end
    if not ent then
      rollback(placed)
      inventory.insert { name = "rail", count = needed }
      return fail("blocked", "rail piece " .. i .. " of " .. #path .. " (" .. n.name .. ") could not be placed at " .. n.x .. "," .. n.y .. "; everything placed was picked up again",
        { x = n.x, y = n.y, piece = n.name, index = i })
    end
    entities[i] = ent
  end

  -- verify the whole line with the game's own rail connectivity
  local prev, prev_exit = start_entity, start_exit
  for i, ent in ipairs(entities) do
    if prev and not connected(prev, prev_exit, ent) then
      rollback(placed)
      inventory.insert { name = "rail", count = needed }
      return fail("disconnected", "rails are not connected at piece " .. i .. " (" .. path[i].name .. " at " .. path[i].x .. "," .. path[i].y .. "); everything placed was picked up again",
        { x = path[i].x, y = path[i].y, index = i })
    end
    prev, prev_exit = ent, path[i].exit
  end

  return done {
    placed = #placed, reused = #path - #placed, rails_used = needed, by_type = counts,
    from = path[1] and { x = path[1].x, y = path[1].y } or nil, to = { x = lx, y = ly, direction = ldir },
    connected = true, continues_existing = start_entity ~= nil, trees_cleared = cleared > 0 and cleared or nil,
  }
end

return M
